#include <vector>
#include <stack>

using namespace std;

class Solution {
public:
    vector<double> getCollisionTimes(vector<vector<int>>& cars) {
        int n = cars.size();
        vector<double> res(n, -1);
        stack<int> st;

        for (int i = n - 1; i >= 0; --i) {
            int p = cars[i][0], s = cars[i][1];
            while (!st.empty()) {
                int j = st.top();
                int pj = cars[j][0], sj = cars[j][1];
                if (s <= sj || (res[j] > 0 && (pj - p) / double(s - sj) > res[j])) {
                    st.pop();
                } else {
                    break;
                }
            }

            if (!st.empty()) {
                int j = st.top();
                res[i] = (cars[j][0] - p) / double(s - cars[j][1]);
            }
            st.push(i);
        }

        return res;
    }
};
